116:     /**
117:      * @notice verfies that the input parameters for deposits
118:      * are correct.
119:      */
120:     function verifyDepositsAndInternalBalances(
121:         address account,
122:         AccountDepositData[] calldata deposits,
123:         AccountInternalBalance[] calldata internalBalances,
124:         uint256 ownerRoots,
125:         bytes32[] calldata proof
126:     ) internal pure {
127:         bytes32 leaf = keccak256(abi.encode(account, deposits, internalBalances, ownerRoots));
128:         require(MerkleProof.verify(proof, MERKLE_ROOT, leaf), "Migration: invalid proof");
129:     }
