131:     /**
132:      * @notice verifies that the signature came from the owner.
133:      * @dev the signature is signed on the L1 blockchain.
134:      * the deposit data itself is not needed, as the signature
135:      */
136:     function verifySignature(
137:         address owner,
138:         address reciever,
139:         uint256 deadline,
140:         bytes calldata signature
141:     ) internal view {
142:         require(block.timestamp <= deadline, "Migration: permit expired deadline");
143:         bytes32 structHash = keccak256(
144:             abi.encode(REDEEM_DEPOSIT_TYPE_HASH, owner, reciever, deadline)
145:         );
146: 
147:         bytes32 hash = _hashTypedDataV4(structHash);
148:         address signer = ECDSA.recover(hash, signature);
149:         require(signer == owner, "Migration: permit invalid signature");
150:     }
