213:     /**
214:      * @notice Hashes in an EIP712 compliant way.
215:      * @dev Returns an Ethereum Signed Typed Data, created from a
216:      * `domainSeparator` and a `structHash`. This produces hash corresponding
217:      * to the one signed with the
218:      * https://eips.ethereum.org/EIPS/eip-712[`eth_signTypedData`]
219:      * JSON-RPC method as part of EIP-712.
220:      *
221:      * Sourced from OpenZeppelin 0.8 ECDSA lib.
222:      */
223:     function _hashTypedDataV4(bytes32 structHash) internal view returns (bytes32) {
224:         return keccak256(abi.encodePacked("\x19\x01", _domainSeparatorV4(), structHash));
225:     }
