227:     /**
228:      * @notice Returns the domain separator for the current chain.
229:      */
230:     function _domainSeparatorV4() internal view returns (bytes32) {
231:         return
232:             keccak256(
233:                 abi.encode(
234:                     EIP712_TYPE_HASH,
235:                     MIGRATION_HASHED_NAME,
236:                     MIGRATION_HASHED_VERSION,
237:                     C.getLegacyChainId(),
238:                     address(this)
239:                 )
240:             );
241:     }
242: }
